package config

import (
	"encoding/json"
	"io/fs"
	"os"
	"slices"
	"strings"
	"testing"
)

const (
	// generatedNotice is the notice every generated template carries, joined
	// onto one line. Comment forms wrap it over several lines.
	generatedNotice = "This file is generated by build-configs. " +
		"Update it only through build-configs.yaml, then regenerate with `build-configs generate`. " +
		"Do not edit it by hand. " +
		"Listing a path in .bcignore opts that file out of generation."

	// scaffoldNotice replaces generatedNotice on a file that is created once
	// and then owned by the developer.
	scaffoldNotice = "This file was created once by `build-configs generate` from build-configs.yaml. " +
		"You own it: edit it freely. Later runs do not overwrite it."

	// codeGeneratedMarker is the line Go tooling, golangci-lint included, reads
	// as "skip this file".
	codeGeneratedMarker = "// Code generated by build-configs. DO NOT EDIT."

	scaffoldStub  = "go-lambda/cmd__[lambda]__main.go.tmpl"
	renovateJSON  = "common/all/.github__renovate.json"
	shellTemplate = "common/vorpal/.github__vorpal-shell.sh"
)

// vorpalMainTemplates are the templates that render cmd/vorpal/main.go.
var vorpalMainTemplates = []string{
	"go-cobra-cli/cmd__vorpal__main.go.tmpl",
	"go-lambda/cmd__vorpal__main.go.tmpl",
	"go-library/cmd__vorpal__main.go.tmpl",
	"terraform/cmd__vorpal__main.go.tmpl",
	"terraform-module/cmd__vorpal__main.go.tmpl",
}

// TestTemplatesCarryGeneratedNotice walks every template and checks the notice
// that tells a developer the rendered file is generated.
func TestTemplatesCarryGeneratedNotice(t *testing.T) {
	templates := os.DirFS(templatesRoot)
	walked := 0
	err := fs.WalkDir(templates, ".", func(p string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return err
		}
		walked++

		raw, err := fs.ReadFile(templates, p)
		if err != nil {
			return err
		}
		t.Run(p, func(t *testing.T) { checkTemplateNotice(t, p, string(raw)) })
		return nil
	})
	if err != nil {
		t.Fatalf("walk %s: %v", templatesRoot, err)
	}
	if walked == 0 {
		t.Fatalf("walk %s found no template files", templatesRoot)
	}
}

func checkTemplateNotice(t *testing.T, p, content string) {
	t.Helper()

	// Only the five vorpal programs carry the Go generated-code marker; the
	// scaffold stub never does, because it is edited by hand.
	wantMarker := slices.Contains(vorpalMainTemplates, p)
	if got := strings.Contains(content, "Code generated"); got != wantMarker {
		t.Errorf("%s: contains \"Code generated\" = %v, want %v", p, got, wantMarker)
	}

	switch {
	case p == renovateJSON:
		checkRenovateNotice(t, content)
	case p == scaffoldStub:
		checkNoticeBeforePackage(t, p, content, scaffoldNotice)
		if strings.Contains(commentText(p, content), generatedNotice) {
			t.Errorf("%s: carries the generated notice, want the scaffold notice only", p)
		}
		// golangci-lint's lax generated-file rule skips a file whose comments
		// say any of these, in any case. The stub is hand-edited, so it must
		// stay linted.
		lower := strings.ToLower(commentText(p, content))
		for _, phrase := range []string{"code generated", "do not edit", "autogenerated file"} {
			if strings.Contains(lower, phrase) {
				t.Errorf("%s: comment contains %q, which makes golangci-lint skip the file", p, phrase)
			}
		}
	case wantMarker:
		if first, _, _ := strings.Cut(content, "\n"); first != codeGeneratedMarker {
			t.Errorf("%s: first line = %q, want %q", p, first, codeGeneratedMarker)
		}
		checkNoticeBeforePackage(t, p, content, generatedNotice)
	case p == shellTemplate:
		if !strings.HasPrefix(content, "#!") {
			t.Errorf("%s: line 1 must be the shebang, got %q", p, firstLine(content))
		}
		if !strings.Contains(commentText(p, content), generatedNotice) {
			t.Errorf("%s: missing generated notice", p)
		}
	default:
		if !strings.Contains(commentText(p, content), generatedNotice) {
			t.Errorf("%s: missing generated notice", p)
		}
	}
}

// checkRenovateNotice expects the notice as the only entry of the top-level
// "description" array, which Renovate accepts and ignores.
func checkRenovateNotice(t *testing.T, content string) {
	t.Helper()

	var doc struct {
		Description []string `json:"description"`
	}
	if err := json.Unmarshal([]byte(content), &doc); err != nil {
		t.Fatalf("%s: invalid JSON: %v", renovateJSON, err)
	}
	if len(doc.Description) != 1 || doc.Description[0] != generatedNotice {
		t.Errorf("%s: description = %q, want [%q]", renovateJSON, doc.Description, generatedNotice)
	}
}

// checkNoticeBeforePackage expects the notice in the comment block above the
// package clause of a Go template.
func checkNoticeBeforePackage(t *testing.T, p, content, notice string) {
	t.Helper()

	above, _, found := strings.Cut(content, "\npackage ")
	if !found {
		t.Fatalf("%s: no package clause", p)
	}
	if !strings.Contains(commentText(p, above), notice) {
		t.Errorf("%s: notice %q not found above the package clause", p, notice)
	}
}

// commentText returns the text of every comment line in content, with the
// comment marker removed and each contiguous block joined onto one line, so a
// wrapped notice compares equal to its one-line form. Blocks are joined with a
// newline so a notice cannot match across two separate blocks.
func commentText(p, content string) string {
	marker := "#"
	if strings.HasSuffix(p, ".go.tmpl") {
		marker = "//"
	}

	var blocks []string
	var block []string
	flush := func() {
		if len(block) > 0 {
			blocks = append(blocks, strings.Join(block, " "))
			block = nil
		}
	}
	for line := range strings.SplitSeq(content, "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "#!") || !strings.HasPrefix(line, marker) {
			flush()
			continue
		}
		block = append(block, strings.TrimSpace(strings.TrimPrefix(line, marker)))
	}
	flush()
	return strings.Join(blocks, "\n")
}

func firstLine(s string) string {
	line, _, _ := strings.Cut(s, "\n")
	return line
}

// hashNoticeLines is generatedNotice as the `#` comment block every `#`-style
// template renders, followed by the blank line that separates it from the
// file's own content. Render tests that pin a whole file prepend it.
const hashNoticeLines = "# This file is generated by build-configs. Update it only through\n" +
	"# build-configs.yaml, then regenerate with `build-configs generate`.\n" +
	"# Do not edit it by hand. Listing a path in .bcignore opts that file\n" +
	"# out of generation.\n" +
	"\n"

func TestHashNoticeLinesMatchGeneratedNotice(t *testing.T) {
	if got := commentText("x", hashNoticeLines); got != generatedNotice {
		t.Errorf("hashNoticeLines = %q, want %q", got, generatedNotice)
	}
}
